import{_ as t,a as n,o as a,a4 as d}from"./chunks/framework.-FZumj2l.js";const p=JSON.parse('{"title":"Delete Channel","description":"","frontmatter":{"outline":false,"examples":[{"id":"gql","title":"Delete Channel","description":"Delete a channel by id. The deleted record is returned as a snapshot so you can confirm what was removed.","query":"mutation DeleteAdminSettingsChannel($input: deleteAdminSettingsChannelInput!) {\\n  deleteAdminSettingsChannel(input: $input) {\\n    adminSettingsChannel {\\n      _id\\n      code\\n      name\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/settings/channels/29\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"deleteAdminSettingsChannel\\": {\\n      \\"adminSettingsChannel\\": {\\n        \\"_id\\": 29,\\n        \\"code\\": \\"thrawaychan29391\\",\\n        \\"name\\": \\"Throwaway 29391\\",\\n        \\"message\\": \\"Channel deleted successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/settings/channels/delete.md","filePath":"api/graphql-api/admin/settings/channels/delete.md","lastUpdated":1783327468000}'),o={name:"api/graphql-api/admin/settings/channels/delete.md"};function s(l,e,i,r,c,h){return a(),n("div",null,e[0]||(e[0]=[d('<h1 id="delete-channel" tabindex="-1">Delete Channel <a class="header-anchor" href="#delete-channel" aria-label="Permalink to &quot;Delete Channel&quot;">​</a></h1><p>Deletes a channel by id. On success the deleted record is returned as a snapshot — <code>_id</code>, <code>code</code>, and <code>name</code> reflect the channel that was removed.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>deleteAdminSettingsChannel(input:)</code></td><td>Mutation</td><td>Delete a channel</td></tr></tbody></table><h2 id="delete-guards" tabindex="-1">Delete guards <a class="header-anchor" href="#delete-guards" aria-label="Permalink to &quot;Delete guards&quot;">​</a></h2><p>The store refuses the delete (returns an <code>errors[]</code> entry, no record removed) when:</p><ul><li>it is the <strong>last remaining channel</strong>, or</li><li>it is the <strong>default app channel</strong> (the channel whose code matches the store&#39;s configured default).</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The returned node is an in-memory snapshot of the just-deleted record — its scalar fields (<code>_id</code>, <code>code</code>, <code>name</code>) still resolve so you can confirm what was removed. The detail-only connections (<code>locales</code>, <code>currencies</code>, <code>inventorySources</code>, <code>translations</code>) come back empty on a delete result.</li><li>Select <strong><code>message</code></strong> for the success confirmation — it resolves to <code>&quot;Channel deleted successfully.&quot;</code> on a successful delete. <code>message</code> is <code>null</code> on read / list / create / update; a failed delete returns a top-level <code>errors[]</code> entry instead.</li></ul><div class="tip custom-block"><p class="custom-block-title">Prerequisites</p><p>The example uses an illustrative <code>id</code>. Replace it with a channel id that exists in your store — use the <a href="./list.html"><code>adminSettingsChannels</code></a> query to discover valid ids.</p></div>',10)]))}const m=t(o,[["render",s]]);export{p as __pageData,m as default};
